        private struct ProbeSample {public double ms;public long main,gc;}
        private static MicroRow MeasureOperation(string name,Action operation)
        {
            var times=new List<double>();long allocated=0;
            for(int warm=0;warm<64;warm++)operation();
            for(int r=0;r<9;r++){long bytes=GC.GetAllocatedBytesForCurrentThread();long start=System.Diagnostics.Stopwatch.GetTimestamp();for(int i=0;i<2048;i++)operation();long elapsed=System.Diagnostics.Stopwatch.GetTimestamp()-start;allocated=Math.Max(allocated,GC.GetAllocatedBytesForCurrentThread()-bytes);times.Add(elapsed*1000000.0/System.Diagnostics.Stopwatch.Frequency/2048);}
            times.Sort();return new MicroRow{operation=name,medianMicroseconds=times[4],maxAllocatedBytes=allocated};
        }
        [UnityTest, Timeout(360000)] public IEnumerator P6EmptyPathBalancedProbe()
        {
            var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
            var pipeline=(ComputePipelineOrchestrator)typeof(MassEngineManager).GetField("pipelineOrchestrator",flags).GetValue(m);
            var shaders=(MassGpuShaderSet)typeof(ComputePipelineOrchestrator).GetField("shaders",flags).GetValue(pipeline);
            var report=new ProbeReport();Assert.IsTrue(m.TryEnableLocalOrderPrototype(out var error),error);var channel=m.LocalOrders;
            var valid=(Func<bool>)typeof(LocalOrderChannel).GetField("contextCurrent",flags).GetValue(channel);
            report.micro.Add(MeasureOperation("delegate-noop",()=>{}));
            report.micro.Add(MeasureOperation("context-validity",()=>{if(!valid())throw new InvalidOperationException("Context invalidated");}));
            report.micro.Add(MeasureOperation("empty-Tick",()=>channel.Tick()));
            report.micro.Add(MeasureOperation("empty-Bind",()=>channel.Bind(shaders)));
            report.micro.Add(MeasureOperation("DisableKeyword",()=>shaders.CombatSimulationShader.DisableKeyword(LocalOrderChannel.Keyword)));
            report.micro.Add(MeasureOperation("empty-AfterDispatch",()=>channel.AfterDispatch(shaders)));
            var main=Unity.Profiling.ProfilerRecorder.StartNew(Unity.Profiling.ProfilerCategory.Internal,"Main Thread",1);
            var gc=Unity.Profiling.ProfilerRecorder.StartNew(Unity.Profiling.ProfilerCategory.Memory,"GC Allocated In Frame",1);
            report.mainThreadRecorder=main.Valid;report.gcRecorder=gc.Valid;
            try
            {
                string[] modes={"off","empty","detached","detached","empty","off","detached","off","empty","empty","off","detached"};
                if(Environment.GetCommandLineArgs().Contains("--p6-perf-reverse"))Array.Reverse(modes);
                for(int w=0;w<modes.Length;w++)
                {
                    string mode=modes[w];
                    if(mode=="off")m.DisableLocalOrderPrototype();
                    else{Assert.IsTrue(m.TryEnableLocalOrderPrototype(out error),error);pipeline.LocalCommands=mode=="detached"?null:m.LocalOrders;}
                    var samples=new List<ProbeSample>(65536);GC.Collect();double warm=Time.realtimeSinceStartupAsDouble+3;while(Time.realtimeSinceStartupAsDouble<warm)yield return null;
                    Assert.AreEqual(WarSandboxBattlePhase.Running,c.Phase);Assert.IsTrue(m.IsBattleRunning);Assert.IsFalse(shaders.CombatSimulationShader.IsKeywordEnabled(LocalOrderChannel.Keyword));
                    double start=Time.realtimeSinceStartupAsDouble,previous=start;
                    while(Time.realtimeSinceStartupAsDouble-start<10){yield return null;double now=Time.realtimeSinceStartupAsDouble;samples.Add(new ProbeSample{ms=(now-previous)*1000,main=main.Valid?main.LastValue:0,gc=gc.Valid?gc.LastValue:0});previous=now;}
                    var hp=new int[m.Buffers.AgentCount];m.Buffers.combatBuffers.hpReadBuffer.GetData(hp);int alive=hp.Count(x=>x>0);Assert.AreEqual(2048,alive);Assert.AreEqual(WarSandboxBattlePhase.Running,c.Phase);Assert.AreEqual(0,m.LocalOrders?.ActiveGroups??0);Assert.AreEqual(0,m.LocalOrders?.SnapshotRequests??0);Assert.AreEqual(0,m.LocalOrders?.AckRequests??0);
                    var ordered=samples.Select(x=>x.ms).OrderBy(x=>x).ToArray();report.rows.Add(new ProbeRow{mode=mode,window=w,frames=samples.Count,alive=alive,phase=c.Phase.ToString(),bytes=m.LocalOrders?.GpuBytes??0,snapshots=m.LocalOrders?.SnapshotRequests??0,acks=m.LocalOrders?.AckRequests??0,medianMs=ordered[ordered.Length/2],p95Ms=ordered[(int)((ordered.Length-1)*.95)],meanMs=ordered.Average(),mainThreadMeanMs=samples.Average(x=>(double)x.main)/1000000,gcBytesMean=samples.Average(x=>(double)x.gc)});
                    using(var file=new StreamWriter(Path.Combine(output,"probe-"+w.ToString("00")+"-"+mode+".csv"))){file.WriteLine("sample,wallMs,mainThreadNs,gcBytes");for(int i=0;i<samples.Count;i++)file.WriteLine(i+","+samples[i].ms.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+samples[i].main+","+samples[i].gc);}
                    File.WriteAllText(Path.Combine(output,"p6-balanced-probe.json"),JsonUtility.ToJson(report,true));
                }
            }
            finally{main.Dispose();gc.Dispose();pipeline.LocalCommands=m.LocalOrders;}
        }
