        private Vector2 ScenarioGoal(int[] ids,Vector2[] p,Vector2 direction)
        {
            Vector2 center=GroupCenter(ids,p),side=new Vector2(-direction.y,direction.x);var nav=m.TerrainNavigation;
            foreach(float distance in new[]{24f,32f,16f,40f})foreach(float lateral in new[]{0f,8f,-8f,16f,-16f})
            {Vector2 candidate=center+direction*distance+side*lateral;if(!nav.TryGetCell(candidate,out int cell))continue;candidate=nav.CellCenter(cell);if(nav.IsFootprintWalkable(candidate,new Vector2(8,8))&&ids.All(id=>nav.AreConnected(p[id],candidate)))return candidate;}
            Assert.Fail("No reachable 8m arrival fixture for "+center+" direction "+direction);return default;
        }
