        private IEnumerator FourGroupScenario(int[][] groups,string name,bool invalidateGeometry)
        {
            m.PauseBattle();Assert.IsTrue(m.TryEnableLocalOrderPrototype(out var error),error);var local=m.LocalOrders;var teams=ScenarioTeams();var starts=ScenarioPositions();
            Vector2[] directions={Vector2.left,Vector2.right,Vector2.down,Vector2.up};var goals=new Vector2[4];var receipts=new LocalOrderReceipt[4];var report=new ScenarioReport{scenario=name,agents=m.Buffers.AgentCount,flowCells=m.Buffers.FlowCellCount,gpuBytes=local.GpuBytes,groupProgress=new float[4]};
            for(int g=0;g<4;g++){goals[g]=ScenarioGoal(groups[g],starts,directions[g]);receipts[g]=local.Submit(local.Epoch,0,g+1,groups[g],LocalOrderKind.Move,goals[g]);yield return ScenarioWait(receipts[g]);RecordCommand(report,g,receipts[g]);}
            Assert.AreEqual(4,local.ActiveGroups);Assert.AreEqual(groups.Sum(x=>x.Length),local.ActiveMembers);Assert.IsTrue(receipts.All(r=>r.GpuExecutingMembers==0),"Paused admissions are not execution");
            m.StartBattle();yield return Frames(120);var moved=ScenarioPositions();
            for(int g=0;g<4;g++){report.groupProgress[g]=Vector2.Dot(GroupCenter(groups[g],moved)-GroupCenter(groups[g],starts),(goals[g]-GroupCenter(groups[g],starts)).normalized);Assert.Greater(report.groupProgress[g],.2f,"Group "+g+" did not move toward its independent goal");foreach(int id in groups[g])Assert.Greater(Vector2.Distance(starts[id],moved[id]),.05f,"Selected member did not actually move: "+id);}
            var selected=new HashSet<int>(groups.SelectMany(x=>x));for(int i=0;i<teams.Length;i++)if(!selected.Contains(i))Assert.AreEqual(0,local.OrderAt(i).slotPlusOne,"Unselected got an override");
            int kept=local.OrderAt(groups[0][0]).sequence;var denied=local.Submit(local.Epoch,0,20,new[]{groups[0][0]},LocalOrderKind.Hold,Vector2.zero);double deadline=Time.realtimeSinceStartupAsDouble+12;while(denied.Status==LocalOrderStatus.AwaitingSnapshot&&Time.realtimeSinceStartupAsDouble<deadline)yield return null;Assert.AreEqual(LocalOrderStatus.Rejected,denied.Status);Assert.AreEqual(kept,local.OrderAt(groups[0][0]).sequence);
            var hold=local.Submit(local.Epoch,0,21,groups[0],LocalOrderKind.Hold,Vector2.zero);yield return ScenarioWait(hold);RecordCommand(report,0,hold);var held=ScenarioPositions();int[] otherSeq=groups.Skip(1).Select(ids=>local.OrderAt(ids[0]).sequence).ToArray();yield return Frames(90);var later=ScenarioPositions();
            Assert.Less(Vector2.Distance(GroupCenter(groups[0],held),GroupCenter(groups[0],later)),1f,"Hold group drifted excessively; avoidance is still allowed");
            for(int g=1;g<4;g++){Assert.AreEqual(otherSeq[g-1],local.OrderAt(groups[g][0]).sequence);Assert.Greater(Vector2.Distance(GroupCenter(groups[g],held),GroupCenter(groups[g],later)),.05f,"Another group stopped with A");}
            // Full-group replacements repeatedly recycle the spare while the other three retain their handles.
            for(int round=0;round<2;round++)for(int g=0;g<4;g++)
            {m.PauseBattle();var pos=ScenarioPositions();var goal=ScenarioGoal(groups[g],pos,round==0?-directions[g]:directions[g]);var r=local.Submit(local.Epoch,0,30+round*4+g,groups[g],LocalOrderKind.Move,goal);yield return ScenarioWait(r);RecordCommand(report,g,r);Assert.AreEqual(4,local.ActiveGroups);for(int h=0;h<4;h++)if(h!=g)Assert.AreNotEqual(r.Sequence,local.OrderAt(groups[h][0]).sequence);m.StartBattle();yield return Frames(8);}
            CollectionAssert.AreEqual(teams,ScenarioTeams());report.teamIdsUnchanged=true;report.groups=local.ActiveGroups;
            if(invalidateGeometry)
            {
                var obstacles=new List<StaticObstacleRect>();for(int i=0;i<m.StaticObstacleCount;i++)if(m.TryGetStaticObstacle(i,out var o))obstacles.Add(o);
                if(obstacles.Count<StaticObstacleMath.MaxObstacleCount)obstacles.Add(new StaticObstacleRect(new Vector2(180,180),new Vector2(2,2)));else{var o=obstacles[0];o.size+=new Vector2(.25f,0);obstacles[0]=o;}
                m.SetStaticObstacles(obstacles.ToArray(),m.StaticObstaclePadding);yield return Frames(3);Assert.IsTrue(local.IsDisposed,"Real obstacle change must invalidate the old navigation context");Assert.AreEqual(0,local.GpuBytes);report.geometryInvalidated=true;
            }
            else{Assert.IsTrue(c.IssueOrder(ArmyOrder.Hold(0)));Assert.AreEqual(0,local.ActiveGroups);Assert.AreEqual(0,local.ActiveMembers);}
            File.WriteAllText(Path.Combine(output,"p6-"+name+".json"),JsonUtility.ToJson(report,true));
        }
